// Python repr() emulation for the value types used by this program:
// integers (BigInt), strings, lists (Array) and dicts (Map with string keys).

// Emulates Python's repr() for str: single quotes by default, double quotes
// when the string contains a single quote but no double quote.
export function pyStrRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (code < 0x20 || code === 0x7f) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else {
      out += ch;
    }
  }
  return out + quote;
}

// Emulates Python's repr() for the supported value graph.
// - BigInt   -> int
// - string   -> str
// - Array    -> list
// - Map      -> dict (insertion order preserved, like CPython)
export function pyRepr(value) {
  if (typeof value === 'bigint') {
    return value.toString();
  }
  if (typeof value === 'string') {
    return pyStrRepr(value);
  }
  if (Array.isArray(value)) {
    return '[' + value.map(pyRepr).join(', ') + ']';
  }
  if (value instanceof Map) {
    const parts = [];
    for (const [k, v] of value) {
      parts.push(pyRepr(k) + ': ' + pyRepr(v));
    }
    return '{' + parts.join(', ') + '}';
  }
  throw new TypeError('pyRepr: unsupported value type');
}

// Minimal black-box reimplementation of DeepDiff(t1, t2) for flat
// dicts mapping string keys to integers, matching the observed output
// of the reference implementation character by character.
//
// Observed behavior:
// - Equal dicts produce an empty report "{}".
// - Per-key report categories, in alphabetical order:
//     dictionary_item_added   -> list of paths for keys only in t2 (t2 order)
//     dictionary_item_removed -> list of paths for keys only in t1 (t1 order)
//     values_changed          -> {path: {'new_value': v2, 'old_value': v1}}
//                                for common keys (t1 order) whose values differ
// - When the key sets differ and the larger dict is "much" larger than the
//   smaller one, the whole dict change is reported at the root instead:
//     {'values_changed': {'root': {'new_value': t2, 'old_value': t1}}}
//   The empirically verified cutoff is: max_len > 3 * min_len, except when
//   one side is empty, where the cutoff is: other side has 2 or more keys.

import { pyRepr } from './pyrepr.mjs';

function dictKeyPath(key) {
  return "root['" + key + "']";
}

function dictsEqual(t1, t2) {
  if (t1.size !== t2.size) return false;
  for (const [k, v] of t1) {
    if (!t2.has(k) || t2.get(k) !== v) return false;
  }
  return true;
}

export function deepDiff(t1, t2) {
  if (dictsEqual(t1, t2)) {
    return '{}';
  }

  const removed = [];
  for (const k of t1.keys()) {
    if (!t2.has(k)) removed.push(k);
  }
  const added = [];
  for (const k of t2.keys()) {
    if (!t1.has(k)) added.push(k);
  }

  const minLen = Math.min(t1.size, t2.size);
  const maxLen = Math.max(t1.size, t2.size);
  const keysDiffer = added.length > 0 || removed.length > 0;
  const rootCutoff = minLen === 0 ? maxLen >= 2 : maxLen > 3 * minLen;

  if (keysDiffer && rootCutoff) {
    const change = new Map([
      ['new_value', t2],
      ['old_value', t1],
    ]);
    const valuesChanged = new Map([['root', change]]);
    const report = new Map([['values_changed', valuesChanged]]);
    return pyRepr(report);
  }

  const report = new Map();
  if (added.length > 0) {
    report.set('dictionary_item_added', added.map(dictKeyPath));
  }
  if (removed.length > 0) {
    report.set('dictionary_item_removed', removed.map(dictKeyPath));
  }
  const valuesChanged = new Map();
  for (const [k, v1] of t1) {
    if (t2.has(k)) {
      const v2 = t2.get(k);
      if (v1 !== v2) {
        valuesChanged.set(
          dictKeyPath(k),
          new Map([
            ['new_value', v2],
            ['old_value', v1],
          ])
        );
      }
    }
  }
  if (valuesChanged.size > 0) {
    report.set('values_changed', valuesChanged);
  }
  return pyRepr(report);
}

// Minimal argparse replica covering the exact CLI surface of the source
// Python script: four required integer options --a, --b, --c, --d, plus -h/--help.
// Error/usage/help text and exit codes mirror Python's argparse.

import { basename } from 'node:path';
import { pyStrRepr } from './pyrepr.mjs';

const OPTION_NAMES = ['--a', '--b', '--c', '--d'];

function prog() {
  return basename(process.argv[1] || 'test12.mjs');
}

function usageLine() {
  return `usage: ${prog()} [-h] --a A --b B --c C --d D`;
}

function printHelpAndExit() {
  const lines = [
    usageLine(),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A',
    '  --b B',
    '  --c C',
    '  --d D',
  ];
  process.stdout.write(lines.join('\n') + '\n');
  process.exit(0);
}

function errorAndExit(message) {
  process.stderr.write(usageLine() + '\n');
  process.stderr.write(`${prog()}: error: ${message}\n`);
  process.exit(2);
}

// Python int(str) semantics: surrounding ASCII whitespace allowed, an
// optional sign, decimal digits with single underscores between digits.
function parsePythonInt(raw) {
  const s = raw.replace(/^[ \t\n\r\f\v]+|[ \t\n\r\f\v]+$/g, '');
  if (!/^[+-]?\d+(_\d+)*$/.test(s)) {
    return null;
  }
  const cleaned = s.replace(/_/g, '');
  try {
    return BigInt(cleaned);
  } catch {
    return null;
  }
}

// argparse treats a token as an option string when it starts with '-',
// unless it looks like a negative number (no option strings here look like
// negative numbers) or it is exactly '-'.
function looksLikeOption(token) {
  if (!token.startsWith('-') || token === '-') return false;
  if (/^-\d+$|^-\d*\.\d+$/.test(token)) return false;
  return true;
}

export function parseArgs(argv) {
  const values = new Map();
  const extras = [];

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    if (token === '-h') {
      printHelpAndExit();
    }

    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      const name = eq === -1 ? token : token.slice(0, eq);
      const inlineValue = eq === -1 ? null : token.slice(eq + 1);

      let resolved = null;
      if (OPTION_NAMES.includes(name)) {
        resolved = name;
      } else if (name === '--help') {
        printHelpAndExit();
      } else {
        // argparse allows unambiguous abbreviations of long options.
        const candidates = [...OPTION_NAMES, '--help'].filter((o) =>
          o.startsWith(name)
        );
        if (candidates.length === 1) {
          resolved = candidates[0];
          if (resolved === '--help') printHelpAndExit();
        } else if (candidates.length > 1) {
          errorAndExit(
            `ambiguous option: ${name} could match ${candidates.join(', ')}`
          );
        }
      }

      if (resolved === null) {
        extras.push(token);
        i += 1;
        continue;
      }

      let raw;
      if (inlineValue !== null) {
        raw = inlineValue;
        i += 1;
      } else if (i + 1 < argv.length && !looksLikeOption(argv[i + 1])) {
        raw = argv[i + 1];
        i += 2;
      } else {
        errorAndExit(`argument ${resolved}: expected one argument`);
      }

      const parsed = parsePythonInt(raw);
      if (parsed === null) {
        errorAndExit(
          `argument ${resolved}: invalid int value: ${pyStrRepr(raw)}`
        );
      }
      values.set(resolved, parsed);
      continue;
    }

    // Unknown short option clusters, negative-number-like tokens and plain
    // positionals all end up as unrecognized arguments.
    extras.push(token);
    i += 1;
  }

  const missing = OPTION_NAMES.filter((o) => !values.has(o));
  if (missing.length > 0) {
    errorAndExit(
      `the following arguments are required: ${missing.join(', ')}`
    );
  }
  if (extras.length > 0) {
    errorAndExit(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return {
    a: values.get('--a'),
    b: values.get('--b'),
    c: values.get('--c'),
    d: values.get('--d'),
  };
}

import { parseArgs } from './argparse.mjs';
import { deepDiff } from './deepdiff.mjs';

const args = parseArgs(process.argv.slice(2));

// Dicts are represented as ordered Maps of string keys to BigInt values,
// mirroring Python's insertion-ordered dicts and arbitrary-precision ints.

// {str(i): i * factor for i in range(count)}
function buildDict(count, factor) {
  const d = new Map();
  for (let i = 0n; i < count; i++) {
    d.set(i.toString(), i * factor);
  }
  return d;
}

function mapValues(d, fn) {
  const out = new Map();
  for (const [k, v] of d) {
    out.set(k, fn(v));
  }
  return out;
}

const obj1 = buildDict(args.b, args.a);
const obj2 = buildDict(args.d, args.c);
const obj3 = mapValues(obj1, (v) => v * 2n);
const obj4 = mapValues(obj2, (v) => v + 10n);

console.log(deepDiff(obj1, obj2)); // r1: 比较两个字典
console.log(deepDiff(obj2, obj3)); // r2: 比较obj2和obj3
console.log(deepDiff(obj3, obj4)); // r3: 比较obj3和obj4
console.log(deepDiff(obj1, obj3)); // r4: 比较obj1和obj3
console.log(deepDiff(obj2, obj4)); // r5: 比较obj2和obj4
console.log(deepDiff(obj1, obj4)); // r6: 比较obj1和obj4
console.log(deepDiff(obj1, obj1)); // r7: 比较相同对象
console.log(deepDiff(new Map(), obj1)); // r8: 比较空字典和obj1
console.log(deepDiff(obj4, new Map())); // r9: 比较obj4和空字典
console.log(deepDiff(obj3, obj3)); // r10: 比较相同对象
